  ["highground.coachbounties.this_path_follows_one_shared_reward_through.0f6fb3"] = "Dieser Pfad folgt einer gemeinsamen Belohnung durch den Anspruch eines Jägers und Ihre Bewertung. Bearbeiten Sie das Beispielziel und verwenden Sie Shared, damit andere Spieler es jagen können.",
  ["highground.coachbounties.choose_next_reward_when_ready_nothing_is.3f6873"] = "Wählen Sie Weiter: Belohnung, wenn Sie fertig sind. Es wurde noch nichts gepostet.",
  ["highground.coachbounties.2_of_3_reward.69e70e"] = "2 von 3 · Belohnung",
  ["highground.coachbounties.set_the_gold_per_kill_one_kill.19457b"] = "Legen Sie das Gold pro Kill fest. Ein Kill und ein beliebiger Abschluss sind die Standardeinstellungen. Eine Notiz und benutzerdefinierte Bedingungen sind optional.",
  ["highground.coachbounties.choose_review_bounty_to_check_the_full.b05001"] = "Wählen Sie Bounty überprüfen, um die vollständige Verpflichtung zu überprüfen.",
  ["highground.coachbounties.3_of_3_review_and_create.a294c5"] = "3 von 3 · Überprüfen und erstellen",
  ["highground.coachbounties.save_the_shared_bounty_its_target_reward.03ecb2"] = "Speichern Sie die gemeinsame Belohnung. Sein Ziel, seine Belohnung und seine Bedingungen bleiben für den Rest dieses Walkthroughs zusammen.",
  ["highground.coachbounties.share_your_bounty.48b966"] = "Teilen Sie Ihre Bounty",
  ["highground.coachbounties.value1_is_ready_share_bounty_copies_a.0dc471"] = "{value1} ist bereit. Kopfgeld teilen kopiert einen Link für andere Jäger. Gemeinsame Belohnungen erscheinen auch im Spiel, daher ist das Senden eines Links optional.",
  ["highground.coachbounties.try_share_bounty_or_next_to_practice.a5db6b"] = "Versuchen Sie Kopfgeld teilen oder Weiter, um die Überprüfung eines Jägeranspruchs zu üben.",
  ["highground.coachbounties.share_bounty.94e67c"] = "Teilen Sie Kopfgeld",
  ["highground.coachbounties.review_the_hunter_s_evidence.9122ff"] = "Überprüfen Sie die Beweise des Jägers",
  ["highground.coachbounties.check_the_evidence_and_bounty_terms_honor.133997"] = "Überprüfen Sie die Beweis- und Kopfgeldbedingungen. Ehrengutschriften können Assists beinhalten; ein gespeicherter Screenshot bestätigt nur die Bildaufnahme. Genehmigen zeichnet die geschuldete Belohnung auf; Ablehnen lehnt den Bericht ab.",
  ["highground.coachbounties.try_approve_or_next_to_activate_it.6ec9dd"] = "Versuchen Sie es mit Genehmigen oder Weiter, um es zu aktivieren. Keine Goldzüge.",
  ["highground.coachbounties.pay_in_the_game_then_record_it.846e10"] = "Bezahlen Sie im Spiel, dann nehmen Sie es auf",
  ["highground.coachbounties.after_paying_the_hunter_through_the_game.c29898"] = "Nachdem du den Jäger im Spiel bezahlt hast, wähle Mark paid. Dies zeichnet die Zahlung auf; Highground überträgt niemals Gold. Aufzeichnung der Zahlung auf dem Board führt zu diesem Bericht.",
  ["highground.coachbounties.try_mark_paid_or_next_to_activate.2dd990"] = "Versuchen Sie es mit Mark paid oder Next, um es zu aktivieren.",
  ["highground.coachbounties.keep_the_review_record.a3d78e"] = "Bewahren Sie den Bewertungsbericht auf",
  ["highground.coachbounties.keep_the_payment_record.dbcd2c"] = "Halten Sie die Zahlungsaufzeichnung",
  ["highground.coachbounties.this_report_keeps_the_bounty_s_target.8e6fa6"] = "Dieser Bericht hält das Ziel, die Belohnung, die Beweise und die Entscheidung des Kopfgelds zusammen. Weitere Kills auf einem größeren Ziel benötigen eine eigene Überprüfung und Zahlung.",
  ["highground.coachbounties.done_returns_to_the_two_bounty_paths.522a07"] = "Erledigt kehrt zu den beiden Kopfgeldpfaden zurück. Echte Bountys und Balancen bleiben unverändert.",
  ["highground.coachbounties.find_a_reward_on_the_shared_board.eb6540"] = "Finde eine Belohnung auf dem Shared Board",
  ["highground.coachbounties.shared_board_lists_rewards_offered_by_other.16ad7b"] = "Das gemeinsame Board listet Belohnungen auf, die von anderen Spielern angeboten werden. Aktualisieren zeigt einen Lader an und bleibt während des Wartens auf Antworten deaktiviert. Neue Kopfgeld-Popups sind eine weitere Möglichkeit, Belohnungen zu entdecken.",
  ["highground.coachbounties.click_shared_board_or_next_to_activate.c968ce"] = "Klicken Sie auf Freigegebenes Board oder Weiter, um es zu aktivieren.",
  ["highground.coachbounties.inspect_a_reward_before_tracking_it.d290ec"] = "Überprüfen Sie eine Belohnung, bevor Sie sie verfolgen",
  ["highground.coachbounties.this_wanted_card_offers_a_reward_for.b6fd13"] = "Diese gesuchte Karte bietet eine Belohnung für {value2}. Öffnen Sie es, um die vollständigen Bedingungen zu lesen.",
  ["highground.coachbounties.click_view_bounty_or_next.dc340a"] = "Klicken Sie auf Kopfgeld anzeigen oder Weiter.",
  ["highground.coachbounties.check_what_earns_the_reward.391d20"] = "Überprüfen Sie, was die Belohnung verdient",
  ["highground.coachbounties.check_the_target_reward_and_expiry_read.94c5fa"] = "Überprüfen Sie das Ziel, Belohnung und Ablauf. Lesen Sie alle benutzerdefinierten Bedingungen darunter; lange Poster scrollen. Kehren Sie zur Karte zurück, um die Verfolgung zu starten. Es ist kein Beitrag erforderlich.",
  ["highground.coachbounties.click_back_to_preview_or_next.d9e682"] = "Klicken Sie auf Zurück zur Vorschau oder Weiter.",
  ["highground.coachbounties.start_tracking_this_target.50a0d0"] = "Starten Sie die Verfolgung dieses Ziels",
  ["highground.coachbounties.choose_start_tracking_the_card_changes_to.b9aa0d"] = "Wählen Sie Tracking starten aus. Die Karte wechselt zu TRACKING und erscheint in Meine Bountys. Das Stoppen der Verfolgung deaktiviert die Benachrichtigungen; es entfernt nicht Ihre Belohnungen oder Berichte. Tracking verspricht kein Gold.",
  ["highground.coachbounties.already_tracking_this_target_next_continues_to.eb8954"] = "Dieses Ziel wird bereits verfolgt. Als nächstes geht es weiter zu seiner Mustersichtung.",
  ["highground.coachbounties.click_start_tracking_next_activates_the_highlighted.5f13d4"] = "Klicken Sie auf Tracking starten. Weiter aktiviert das markierte Steuerelement.",
  ["highground.coachbounties.sample_event_your_target_is_nearby.f5e819"] = "Beispielereignis: Ihr Ziel ist in der Nähe",
  ["highground.coachbounties.a_sighting_detects_value2_the_same_target.a41058"] = "Eine Sichtung erkennt {value2}, das gleiche Ziel, das Sie zur Verfolgung ausgewählt haben. Schließen Sie diese Warnung, um mit einem Beispielkill fortzufahren, oder prüfen Sie das Poster erneut.",
  ["highground.coachbounties.close_the_wanted_alert_or_next_to.724954"] = "Schließen Sie die gesuchte Benachrichtigung oder klicken Sie auf Weiter, um die Schließen-Taste zu aktivieren.",
  ["highground.coachbounties.sample_event_the_target_is_killed.ca18c1"] = "Beispielereignis: Das Ziel wird getötet",
  ["highground.coachbounties.the_addon_creates_the_report_automatically_a.1fa40f"] = "Das Add-on erstellt den Bericht automatisch. Ein lesbarer tödlicher Schlag wird bestätigt; Ehrengutschrift kann Assists beinhalten. Das Häkchen bedeutet nur, dass das Bild gespeichert wurde. Öffnen Sie den Bericht, um der Überprüfung zu folgen.",
  ["highground.coachbounties.click_view_sample_report_copying_proof_is.ecb999"] = "Klicken Sie auf Beispielbericht anzeigen. Kopiernachweis ist optional; kein realer Screenshot oder Bericht wird gesendet.",
  ["highground.coachbounties.bounty_ignored.3d5adf"] = "Bounty ignoriert",
  ["highground.coachbounties.follow_your_own_claim.e2d148"] = "Folgen Sie Ihrem eigenen Anspruch",
  ["highground.coachbounties.this_target_was_not_added_to_your.871630"] = "Dieses Ziel wurde nicht zu deinen verfolgten Kopfgeldern hinzugefügt. Starten Sie den Jagdpfad erneut, wann immer Sie einen Anspruch versuchen möchten.",
  ["highground.coachbounties.your_report_is_saved_its_next_step.c8431b"] = "Ihr Bericht wird gespeichert. Sein nächster Schritt erklärt die Lieferung, Bewertung oder Zahlung. Der Poster überprüft die Belohnung und zahlt durch das Spiel. Verwenden Sie Belohnung anfordern oder einen verpassten Kill melden nur, wenn die Erkennung einen Tod verpasst hat.",
