  ["highground.coachmap.enemies_on_your_world_map.7062f3"] = "Feinde auf der Weltkarte",
  ["highground.coachmap.this_is_wow_s_world_map_with.e5b392"] = "Dies ist die Weltkarte von WoW mit fünf Beispielfeinden in Warsong Gulch. In einem Match erscheinen dieselben Pins auch auf der Schlachtfeldkarte (Shift+M). Nur beobachtete Feinde erhalten eine Position.",
  ["highground.coachmap.warsong_gulch_is_unavailable_in_this_client.da444f"] = "Warsong Gulch ist in diesem Client nicht verfügbar. Dies ist deine normale Weltkarte. Kehren Sie zu Guides zurück, um eine andere Funktion auszuprobieren.",
  ["highground.coachmap.start_with_a_fresh_sighting.d7f307"] = "Beginnen Sie mit einer frischen Sichtung",
  ["highground.coachmap.this_bright_rogue_pin_is_a_fresh.bbd705"] = "Diese helle Schurkennadel ist eine frische Sichtung. Bewegen Sie die Maus darüber, um zu lesen, wer gesehen wurde und wer sie beobachtet hat.",
  ["highground.coachmap.hover_the_highlighted_enemy_then_choose_next.7c672d"] = "Fahre mit der Maus über den markierten Feind und wähle dann Weiter aus.",
