  ["highground.coachmap.older_sightings_fade.039a3d"] = "Ältere Sichtungen verblassen",
  ["highground.coachmap.this_faded_mage_was_last_seen_36.2fe437"] = "Dieser verblasste Magier wurde zuletzt vor 36 Sekunden gesehen. Die Zeit ist das Alter der Sichtung. Sie sind möglicherweise umgezogen; dies ist keine Live-Position.",
  ["highground.coachmap.a_location_can_be_approximate.08cdfb"] = "Ein Standort kann ungefähr sein",
  ["highground.coachmap.the_means_an_approximate_position_such_as.e5e407"] = "Das ~ bedeutet eine ungefähre Position, wie z.B. eine bekannte Fläche. Fahren Sie mit der Maus, um zu sehen, warum es ungefähr ist. Die Beobachtung eines Teamkollegen verbessert die Deckung, ohne unsichtbare Feinde aufzudecken.",
  ["highground.coachmap.use_the_whole_picture.b9e5f8"] = "Verwenden Sie das ganze Bild",
  ["highground.coachmap.compare_fresh_pins_older_sightings_and_the.a2fa1f"] = "Vergleichen Sie frische Pins, ältere Sichtungen und das Ziel, bevor Sie eine Route auswählen. Diese Beispielsichtungen bleiben außerhalb von Live-Tracking und Gruppenfreigabe. Fertig stellt die vorherige Karte wieder her.",
  ["highground.coachmap.warsong_gulch_is_unavailable_in_this_client.ccb80d"] = "Warsong Gulch ist in diesem Client nicht verfügbar. Verwenden Sie Hilfslinien, um zurückzukehren.",
  ["highground.coachmap.use_replay_to_reopen_warsong_gulch_on.5dd141"] = "Benutzt die Wiederholung, um die Kriegsliedschlucht auf der Weltkarte erneut zu öffnen.",
