  ["highground.coachpreferences.bar_textures_colours_and_borders_are_shared.cbec37"] = "Texturen, Farben und Rahmen der Balken werden gemeinsam genutzt. Passen Sie die Größe jedes Panels in der Aussehen-Seite seines eigenen Addons an.",
  ["highground.coachpreferences.settings_live_with_their_addon.f2c359"] = "Einstellungen live mit ihrem Addon",
  ["highground.coachpreferences.use_an_addon_s_settings_appearance_commands.b1a987"] = "Verwenden Sie die Einstellungen, das Aussehen, die Befehle, die Vorschauen und die Hilfeseiten eines Addons. Schlachtfeld-Panels verwenden /hg bg test. Führen Sie /hg test oder /hg test stop aus Hilfe und Befehlen aus, um alle Vorschauen zu wechseln oder zu beenden. Übersicht und aktivieren Sie Kontrollen, ob das Add-on nach dem Neuladen läuft. Gemeinsame Einstellungen wirken sich auf alle Addons aus.",
  ["highground.coachpreferences.keep_the_panels_you_want.abbf0b"] = "Behalten Sie die gewünschten Panels",
  ["highground.coachpreferences.choose_shared_preferences.f69dd0"] = "Gemeinsame Einstellungen auswählen",
  ["highground.coachpreferences.checked_means_enabled_all_available_feature_switches.16b69f"] = "Aktiviert bedeutet aktiviert. Alle verfügbaren Funktionsschalter werden hier angezeigt; scrollen Sie, um den Rest zu sehen.",
  ["highground.coachpreferences.checked_means_enabled_this_switch_shows_the.de650b"] = "Aktiviert bedeutet aktiviert. Dieser Schalter zeigt den Highground-Minimap-Button an.",
  ["highground.coachpreferences.choose_the_warnings_you_want.2794f4"] = "Wählen Sie die gewünschten Warnungen aus",
