  ["highground.coachpreferences.this_changes_your_real_alert_preference.ecd3f5"] = "Dies ändert Ihre tatsächliche Benachrichtigungseinstellung.",
  ["highground.coachpreferences.go_straight_to_an_addon_s_alerts.46dd58"] = "Gehen Sie direkt zu den Benachrichtigungen eines Addons",
  ["highground.coachpreferences.the_battlegrounds_nearby_and_bounties_links_open.676c0b"] = "Die Schlachtfelder-, In der Nähe- und Kopfgeld-Links öffnen ihre Text- und Soundsteuerung direkt. Deaktivierte Add-ons werden verfügbar, nachdem Sie sie in Add-ons aktivieren und neu laden.",
  ["highground.coachpreferences.click_battlegrounds_or_next_to_open_its.68ede3"] = "Klicken Sie auf Schlachtfelder oder Weiter, um die Benachrichtigungssteuerung zu öffnen.",
  ["highground.coachpreferences.enemy_stealth_stays_available_here_even_when.63bf57"] = "Feindliche Tarnung bleibt hier verfügbar, auch wenn ein Addon deaktiviert ist.",
  ["highground.coachpreferences.choose_text_sound_or_both.306e9e"] = "Wählen Sie Text, Ton oder beides",
  ["highground.coachpreferences.these_switches_belong_to_battlegrounds_settings_nearby.0373c0"] = "Diese Schalter gehören zu den Battlegrounds-Einstellungen. In der Nähe und Bounty haben ihre eigenen. Ihre gemeinsame Warnstufe und Ihr Master-Sound gelten weiterhin.",
  ["highground.coachpreferences.enemy_stealth_applies_across_addons_other_alert.fa92cd"] = "Feindliche Tarnung gilt für alle Add-ons. Andere Alert-Kategorien leben in den Einstellungen ihres Addons. Ihre gemeinsame Warnstufe und Ihr Master-Sound gelten weiterhin.",
  ["highground.coachpreferences.highground_is_the_only_download_you_need.f138df"] = "Highground ist der einzige Download, den Sie benötigen",
  ["highground.coachpreferences.addons_brings_the_addon_switches_settings_shortcuts.df8aff"] = "Addons bringt die Addon-Schalter, Einstellungen Shortcuts und Anleitungen zusammen. Entfernen Sie alle separaten eigenständigen Downloads. Bewahren Sie jeden Modulordner und beide erforderlichen Daten-Addons auf. Das Deaktivieren eines Daten-Addons verhindert, dass Highground geladen wird.",
  ["highground.coachpreferences.a_disabled_module_does_not_activate_a.e4cf84"] = "Ein deaktiviertes Modul aktiviert keine eigenständige Kopie. Nichts wird durch diese Anleitung entfernt.",
  ["highground.coachpreferences.choose_which_addons_run.892aae"] = "Wählen Sie, welche Addons ausgeführt werden sollen",
  ["highground.coachpreferences.enable_addon_is_the_same_per_character.e05474"] = "Enable addon ist der gleiche pro-Charaktere-Schalter wie WoW's AddOn List. Alle sechs Sub-Addons sind im Download Highground enthalten.",
  ["highground.coachpreferences.these_are_real_switches_you_can_continue.862243"] = "Das sind echte Schalter. Sie können weitermachen, ohne etwas zu ändern.",
  ["highground.coachpreferences.visit_settings_or_replay_a_guide.e879b6"] = "Einstellungen aufrufen oder eine Anleitung wiedergeben",
  ["highground.coachpreferences.visit_opens_this_addon_s_overview_and.64e863"] = "Besuchen öffnet die Übersicht und Einstellungen dieses Add-ons. Starten, Fortsetzen oder Wiederholen öffnet seinen Walkthrough und behält seinen gespeicherten Platz.",
  ["highground.coachpreferences.visit_leaves_this_walkthrough_next_continues_without.da36c5"] = "Besuch verlässt diese Walkthrough. Weiter geht es ohne Besuch.",
  ["highground.coachpreferences.recognize_subaddons_in_the_sidebar.8ccd1c"] = "Sub-Add-ons in der Seitenleiste erkennen",
  ["highground.coachpreferences.each_subaddon_has_a_small_crest_and.3b587c"] = "Jedes Subaddon hat ein kleines Wappen und einen Akzentstreifen. Erweitern Sie den Abschnitt für Übersicht und aktivieren, Einstellungen, Darstellung (sofern verfügbar), Befehle und Vorschauen und Anleitungen.",
  ["highground.coachpreferences.shared_preferences_saved_setups_and_help_apply.3e1969"] = "Gemeinsame Einstellungen, gespeicherte Einstellungen und Hilfe gelten über ein einzelnes Add-on hinaus.",
  ["highground.coachpreferences.keep_your_settings_when_disabling_an_addon.518274"] = "Behalten Sie Ihre Einstellungen beim Deaktivieren eines Addons bei",
  ["highground.coachpreferences.changing_a_switch_takes_effect_after_reload.145c67"] = "Die Änderung eines Schalters wird nach dem Neuladen wirksam. Gespeicherte Panel-Einstellungen und Datensätze bleiben intakt. Panel auf Karten in der Nähe und Arena anzeigen ändert nur die Panel-Einstellung. Die Änderung Enable addon back before reload bricht diese Änderung ab.",
  ["highground.coachpreferences.profiles_do_not_enable_or_disable_addons.a7920d"] = "Profile aktivieren oder deaktivieren keine Add-ons.",
  ["highground.coachpreferences.reload_when_you_are_ready.225a57"] = "Reload, wenn Sie bereit sind",
  ["highground.coachpreferences.after_changing_a_switch_reload_to_apply.8a851b"] = "Nachdem Sie einen Schalter geändert haben, erscheint Reload to apply auf Addons. Nachladen außerhalb des Kampfes, um aktivierte Module zu starten und deaktivierte zu stoppen. Der Guide wird nie automatisch neu geladen.",
  ["highground.coachpreferences.next_continues_without_reloading.acc474"] = "Next fährt ohne Nachladen fort.",
  ["highground.coachpreferences.find_commands_and_their_controls.a1ca25"] = "Suchen von Befehlen und deren Steuerelementen",
  ["highground.coachpreferences.each_addon_has_a_commands_page_help.cc07e2"] = "Jedes Addon hat eine Befehlsseite; Hilfe und Befehle kombiniert sie. Jeder Befehl verwendet eine Zeile. Bewegen Sie den Mauszeiger für die vollständige Syntax und Aliase. Die Schaltfläche öffnet Einstellungen, führt die Aktion aus oder öffnet beschriftete Felder für ihre Werte.",
  ["highground.coachpreferences.browsing_is_safe_action_buttons_can_change.33ba22"] = "Browsen ist sicher. Aktionsschaltflächen können reale Einstellungen ändern; diese Anleitung klickt sie nicht an.",
  ["highground.coachpreferences.discover_channel_members.5df463"] = "Channel-Mitglieder entdecken",
  ["highground.coachpreferences.your_own_character_counts_immediately_a_complete.2a1246"] = "Der eigene Charakter zählt sofort. Eine vollständige Channel-Mitgliederliste fügt andere Mitglieder hinzu, bevor ihre Addon-Ankündigungen eintreffen. Mitglieder aktualisieren zeigt einen Lader an und bleibt während des Wartens deaktiviert. Versuchen Sie es, um eine Beispielabfahrt zu sehen.",
  ["highground.coachpreferences.this_sample_does_not_request_a_live.d4e060"] = "Dieses Beispiel fordert keine Live-Mitgliederliste an und sendet keine Nachrichten.",
  ["highground.coachpreferences.membership_and_version_reports_are_different.84c36a"] = "Mitgliedschafts- und Versionsberichte unterscheiden sich",
  ["highground.coachpreferences.a_channel_member_may_not_have_a.590af5"] = "Ein Channel-Mitglied kann kein reagierendes Addon haben. Mitglieder ohne Ankündigung haben ihre eigene Zählung. Versionen kommen nur von empfangenen Ankündigungen; überprüfen Sie Update-Benachrichtigungen in Ihrem Add-on-Manager.",
  ["highground.coachpreferences.keep_useful_counts_when_a_list_is.120802"] = "Nützliche Zählungen beibehalten, wenn eine Liste nicht verfügbar ist",
  ["highground.coachpreferences.an_incomplete_or_unavailable_member_list_keeps.d5bf62"] = "Eine unvollständige oder nicht verfügbare Mitgliederliste behält die letzte vollständige Liste für kurze Zeit bei und fällt dann auf die letzten Ankündigungen zurück. Zählungen können Charaktere enthalten, die seitdem gegangen sind. Die Gruppen- und Gildenentdeckung verwendet weiterhin Ankündigungen.",
  ["highground.coachpreferences.close_the_guide_to_return_to_live.65ab77"] = "Schließen Sie den Guide, um zu den Livezählungen zurückzukehren. Ermittlungseinstellungen sind nur in diesem Beispiel deaktiviert.",
