  ["shared.previewsamples.portraits_use_your_selected_player_or_your.6ec2ed"] = "Porträts verwenden deinen ausgewählten Spieler oder deinen Charakter als beschriftetes Beispiel. Dies legt nie eine Belohnung auf sie. Live-Benachrichtigungen stammen von Sichtungen, einschließlich Zielen, Mouseover und Namensschildern.",
  ["shared.previewsamples.wanted_board.b69f07"] = "Wanted Board",
  ["shared.previewsamples.wanted_cards_and_full_posters.c0244c"] = "Gesuchte Karten und Vollposter",
  ["shared.previewsamples.click_the_wanted_card_or_view_bounty.b1ae32"] = "Klicken Sie auf die gewünschte Karte oder auf Kopfgeld anzeigen, um jeden Beitragenden, seine Bedingungen, Finanzierung und Ablauf zu überprüfen. Aktualisieren zeigt eine deaktivierte Taste und einen deaktivierten Lader, während Beispielbelohnungen eintreffen.",
  ["shared.previewsamples.start_tracking_adds_a_target_to_my.e9b443"] = "Tracking starten fügt ein Ziel zu Meine Belohnungen hinzu. Nach einem erkannten Kill öffnet Bericht anzeigen den Status. Poster setzen das Ziel und die Belohnung zuerst, verwenden die Pergamentbreite für Details und scrollen bei Bedarf. Nicht verfügbare Porträts sind beschriftet.",
  ["shared.previewsamples.create_terms.1ea507"] = "Erstellen & Bedingungen",
  ["shared.previewsamples.build_a_sample_bounty.01af6d"] = "Erstellen Sie ein Beispiel-Kopfgeld",
  ["shared.previewsamples.three_steps_target_reward_review_nothing_is.cc55e8"] = "Drei Schritte: Ziel, Belohnung, Überprüfung. Bis zur endgültigen Bestätigung wird nichts gespeichert. Ein Kill mit beliebigem Ende ist der Standard.",
  ["shared.previewsamples.save_returns_to_the_tour_sharing_is.631c62"] = "Speichern Sie Rückkehren zur Tour. Das Teilen ist optional. Private Tracking kann Null Gold verwenden; geteilte Belohnungen benötigen einen positiven Betrag und ein Ablaufdatum. Bevorzugte Oberflächen erfordern die Plakatprüfung. Es wird keine Live-Belohnung erstellt.",
  ["shared.previewsamples.use_gold_across_your_characters.423446"] = "Verwende Gold für deine Charaktere",
  ["shared.previewsamples.see_a_sample_wallet_and_the_bag.2652f4"] = "Sehen Sie eine Beispiel-Brieftasche und die Tasche Gold Tooltip. Probieren Sie beide Schalter aus, und geben Sie dann eine Belohnung ein, die größer ist als der verfügbare Betrag in Erstellen & Bedingungen.",
  ["shared.previewsamples.account_tracking_is_on_by_default_requiring.faa230"] = "Das Account-Tracking ist standardmäßig aktiviert. Die Anforderung von genügend Gold ist standardmäßig deaktiviert: Eine Überbudget-Belohnung warnt, kann aber erstellt werden. Balancen sind auf diesen Realm oder Forever Realmset beschränkt. Alt Guthaben werden aktualisiert, wenn Sie sich anmelden; Zahlungen und Überweisungen bleiben manuell.",
  ["shared.previewsamples.guild_approval.d5172b"] = "Gildengenehmigung",
  ["shared.previewsamples.submit_and_approve_a_guild_bounty.93c32d"] = "Gilden-Kopfgeld einreichen und genehmigen",
  ["shared.previewsamples.try_awaiting_approval_officer_approval_and_rejection.1aed32"] = "Versuchen Sie, auf Genehmigung, Genehmigung des Beamten und Ablehnung zu warten, und überprüfen Sie dann die resultierende gesuchte Karte. Diese Rollen sind in der Tour auch ohne Gilde verfügbar.",
  ["shared.previewsamples.approved_guild_rewards_can_show_a_new.36cbe4"] = "Genehmigte Gildenbelohnungen können ein NEUES BOUNTY-Poster zeigen. Dies kündigt eine Belohnung an, nicht eine Sichtung. Das Teilen einer Belohnung mit Gilden- und globalen Boards führt nicht zu einer zweiten Zahlungsverpflichtung. Bei Forever werden Community-Belohnungen nur mit Mitgliedern Ihres Regelsatzes synchronisiert.",
  ["shared.previewsamples.shared_arrivals.7e4e7c"] = "Gemeinsame Ankünfte",
  ["shared.previewsamples.a_bounty_matches_your_filters.542556"] = "A bounty entspricht Ihren Filtern",
  ["shared.previewsamples.use_start_tracking_or_ignore_on_the.ac8ad1"] = "Verwenden Sie Start tracking oder Ignore auf dem eingehenden Poster. Testen Sie Beispiele für Benachrichtigungseinstellungen und Finanzierungsstatus. Dieses Ziel wurde nicht entdeckt.",
  ["shared.previewsamples.the_notification_minimum_counts_rewards_with_current.7ea6f7"] = "Das Benachrichtigungsminimum zählt Belohnungen mit aktuellen verfügbaren Guthabenberichten. Importierte, veraltete oder unfinanzierte Angebote bleiben unterscheidbar. Das Verfolgen verspricht kein Gold; das Ignorieren macht die Kopfgeld- und Sichtungswarnungen des Ziels stumm.",
  ["shared.previewsamples.grow_a_bounty_s_pot.fc063b"] = "Wachsen Sie einen Kopfgeldtopf",
  ["shared.previewsamples.add_a_sample_contribution_review_the_original.3e1e7c"] = "Fügen Sie einen Beispielbeitrag hinzu, überprüfen Sie die Bedingungen des ursprünglichen Posters und sehen Sie die kombinierte Belohnungsaktualisierung.",
  ["shared.previewsamples.accepting_the_terms_means_the_original_poster.cb648e"] = "Die Annahme der Bedingungen bedeutet, dass der ursprüngliche Poster entscheidet, ob ein Anspruch qualifiziert ist. Mitwirkende schulden ihre Beträge demselben akzeptierten Jäger. Gold wird nicht vom Addon gehalten oder übertragen.",
  ["shared.previewsamples.share_import.d10b63"] = "Teilen & importieren",
  ["shared.previewsamples.copy_a_bounty_link_and_review_an.e6954f"] = "Kopieren eines Bounty-Links und Überprüfen eines Imports",
  ["shared.previewsamples.sharing_outside_the_addon_is_optional_copy.b960a6"] = "Das Teilen außerhalb des Addons ist optional. Kopiere einen globalen, Gilden- oder privaten Kopfgeldlink und sieh dir dann einen Beispielimport an.",
  ["shared.previewsamples.choose_select_link_to_copy_press_ctrl.75c0bf"] = "Wählen Sie Link zum Kopieren auswählen, drücken Sie Ctrl+C und senden Sie den Bounty-Link. Der Empfänger wählt Kopfgeld importieren. Das Teilen im Chat ist für private und Gruppen-Bountys verfügbar. Discord Kanal öffnet das gemeinsame Board-Ziel separat. Tour-Links sind absichtlich außerhalb der Tour ungültig.",
  ["shared.previewsamples.kills_reports.48e18a"] = "Kills & Berichte",
  ["shared.previewsamples.detected_kills_create_reports_automatically.0ec7e1"] = "Erkannte Kills erstellen automatisch Berichte",
  ["shared.previewsamples.use_view_sample_report_to_follow_review.4dce46"] = "Verwenden Sie Beispielbericht anzeigen, um der Überprüfung zu folgen. Versuchen Sie wiederholte Kills und Screenshot Erfolg, Fehler oder erneut versuchen. Der Kopiernachweis ist optional.",
  ["shared.previewsamples.readable_killing_blows_are_confirmed_locally_named.83de2e"] = "Lesbare tödliche Schläge werden lokal bestätigt. Named Honor Credit kann Assists beinhalten. Ein Screenshot-Häkchen bestätigt, dass nur das Bild gespeichert wurde. Belohnungsgenehmigung und Zahlung bleiben getrennt; manuelles Reporting ist für verpasste Erkennungen. Diese Tour nimmt keine Screenshots auf.",
  ["shared.previewsamples.follow_reports_through_review_and_payment.7bf30e"] = "Berichte durch Überprüfung und Zahlung verfolgen",
  ["shared.previewsamples.browse_hunter_and_poster_examples_awaiting_review.ee1784"] = "Durchsuchen Sie Hunter- und Poster-Beispiele: Warten auf Überprüfung, genehmigt, bezahlt und abgelehnt. Probieren Sie Genehmigen, Ablehnen und Bezahlt markieren als Beispielposter aus.",
  ["shared.previewsamples.hunters_cannot_approve_their_own_reports_the.8e822e"] = "Jäger können ihre eigenen Berichte nicht genehmigen. Der Poster überprüft die Beweise und zahlt manuell durch das Spiel, dann zeichnet diese Zahlung auf. Wiederholte Kills können auf ein Multi-Kill-Ziel angerechnet werden, ohne zweimal für dieselbe Belohnung zu bezahlen.",
  ["shared.previewsamples.review_enemies_suggested_by_death_reports.470074"] = "Überprüfen Sie Gegner, die von Todesberichten vorgeschlagen werden",
  ["shared.previewsamples.inspect_sample_reports_review_a_prefilled_bounty.a7057d"] = "Prüfen Sie Beispielberichte, überprüfen Sie ein vorgefülltes Kopfgeld, verwerfen Sie den Vorschlag oder ignorieren Sie den Feind.",
  ["shared.previewsamples.suggestions_combine_your_deaths_and_participating_guild.4596f6"] = "Vorschläge kombinieren deine Todesfälle und teilnehmenden Gildenberichte innerhalb des konfigurierten Fensters. Sie sind Leads zur Überprüfung, nicht server-verifizierter Kill-Beweis. Nichts wird veröffentlicht, bis Sie eine Zielgruppe auswählen und speichern.",
  ["shared.previewtest.leave_combat_before_starting_a_bounty_preview.0cf3f1"] = "Verlasse den Kampf, bevor du eine Kopfgeld-Vorschau startest.",
  ["shared.previewview.nearby_row.e41e3b"] = "ZEILE „IN DER NÄHE“",
  ["shared.previewview.85_tarren_mill_now.70f627"] = "85 · Tarren Mill · jetzt buchen",
